        public InputList<Inputs.AzureVirtualMachineVolumeGetArgs> Volumes
        {
            get => _volumes ?? (_volumes = new InputList<Inputs.AzureVirtualMachineVolumeGetArgs>());
            set => _volumes = value;
        }

        /// <summary>
